"""Summarize mailbox letters without modifying the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
RESOLVING = {"DONE", "BLOCKED", "NEEDS-USER", "FAILED"}


def read_letter(path, now):
    try:
        with path.open(encoding="utf-8", newline="") as stream:
            lines = stream.read().split("\n")
    except (OSError, UnicodeError):
        return None, "no_frontmatter"
    # Split only at LF; keep standalone control characters inside values.
    lines = [line[:-1] if i < len(lines) - 1 and line.endswith("\r") else line
             for i, line in enumerate(lines)]
    if not lines or lines[0] != "---":
        return None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if not all(fields.get(key) for key in ("id", "from", "to", "status")):
        return None, "no_field"
    try:
        at = datetime.fromisoformat(fields["at"])
    except (KeyError, ValueError):
        return None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    if not NAME.match(path.name):
        return None, "bad_name"
    try:
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, "bad_name"
    return {"id": fields["id"], "from": fields["from"], "to": fields["to"],
            "status": fields["status"], "re": fields.get("re", ""),
            "age_min": (now - at) // timedelta(minutes=1)}, None


def summarize(root, now):
    boxes = {}
    paths = []
    for mailbox in sorted(root.iterdir(), key=lambda path: path.name):
        if mailbox.name.startswith(".") or mailbox.is_symlink() or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for directory in (inbox, inbox / "done"):
            if directory.is_symlink() or not directory.is_dir():
                continue
            for path in directory.iterdir():
                if (path.name.endswith(".md") and not path.name.startswith(".")
                        and not path.is_symlink() and path.is_file()):
                    paths.append(path)
    paths.sort(key=lambda path: path.relative_to(root).as_posix())
    seen = set()
    letters = []
    bad = []
    for path in paths:
        relative = path.relative_to(root).as_posix()
        letter, why = read_letter(path, now)
        if why is None and letter["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(letter["id"])
        letter["where"] = "done" if path.parent.name == "done" else "inbox"
        letters.append(letter)
        box = boxes[path.relative_to(root).parts[0]]
        if letter["where"] == "done":
            box["done"] += 1
        else:
            counts = box["inbox"]
            counts[letter["status"]] = counts.get(letter["status"], 0) + 1
    resolved = {letter["re"] for letter in letters if letter["re"]
                and letter["status"] in RESOLVING}
    opened = [{key: letter[key] for key in ("id", "from", "to", "where", "age_min")}
              for letter in letters if letter["status"] == "REQUEST"
              and letter["id"] not in resolved]
    opened.sort(key=lambda letter: (letter["to"], letter["id"]))
    return {"v": 1, "open": opened, "boxes": boxes,
            "bad": sorted(bad, key=lambda item: (item["file"], item["why"]))}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox todo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True)
    args = parser.parse_args(argv)
    try:
        now = datetime.fromisoformat(args.now)
    except ValueError:
        parser.error("--now must be an ISO datetime with a timezone")
    if now.tzinfo is None:
        parser.error("--now must have a timezone")
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    print(json.dumps(summarize(args.folder, now), ensure_ascii=False,
                     separators=(",", ":")))
    return 0
